const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

// Set the canvas dimensions
canvas.width = 400;
canvas.height = 400;

// Define the pendulum properties
const GRAVITY = 9.81; // m/s^2
const LENGTH = 100; // meters
const MASS = 1; // kg

// Define the initial angle (in radians)
let initialAngle = parseFloat(document.getElementById('initial-angle').value) * Math.PI / 180;

// Define the pendulum's initial velocity (0 by default)
let velocity = 0;

// Define the integration time step (ms)
let dt = 10;

// Main simulation loop
function simulate() {
  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Calculate the new angle and velocity based on the physics equations
  let angularAcceleration = -GRAVITY / LENGTH * Math.sin(initialAngle);
  velocity += angularAcceleration * dt;
  initialAngle += velocity * dt;

  // Draw the pendulum
  let pendulumX = canvas.width / 2;
  let pendulumY = canvas.height / 2 - LENGTH * Math.sin.initialAngle();
  ctx.beginPath();
  ctx.arc(pendulumX, pendulumY, 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();

  // Update the display
  document.getElementById('initial-angle').value = Math.round(initialAngle * 180 / Math.PI);
  requestAnimationFrame(simulate);
}

// Release the pendulum when the button is clicked
document.getElementById('release-button').addEventListener('click', () => {
  simulate();
});

// Initialize the simulation
