```
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-lambda-go/lambda"
	"github.com/aws/aws-lambda-go/lambda/intents"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	tagName := "backup_type"

aeperateSnapshots := []struct{
	 retention int `json:"retention"`
	 tagValue string `json:"tagValue"`
	}{
		{14, "monthly"},
		{10, "daily"},
		{4, "weekly"},
		{1, "yearly"},
	}

	for _, retention := range aeperateSnapshots {
	-input, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
			Filters: []*ec2.Filter{
				{
					Name: aws.String("tag:" + tagName),
				 Values: []*string{aws.String(retention.tagValue)},
				},
			},
		})
		if err != nil {
			log.Println(err)
			continue
		}

		log.Printf("Found %d snapshots for tag %s value %s", len(*input.Snapshots), tagName, retention.tagValue)

		// Sort snapshots by creation time
		sortedSnapshots := []*ec2.Snapshot{}
		for _, snap := range *input.Snapshots {
			sortedSnapshots = append(sortedSnapshots, snap)
		}
		sort.Slice(sortedSnapshots, func(i, j int) bool {
			return *sortedSnapshots[i].StartTime.Before(*sortedSnapshots[j].StartTime)
		})

		// Delete snapshots older than retention period
		for _, snap := range sortedSnapshots[:len(*input.Snapshots)-retention.retention] {
			_, err := ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(*snap.SnapshotId),
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	return nil, nil
}

func main() {
	lambda.Start(handler)
}
